solution:
class Workout:
    def __init__(self, minutes, calories):
        self.minutes = minutes
        self.calories = calories

class Run(Workout):
    def __init__(self, minutes, calories, distance_km):
        Workout.__init__(self, minutes, calories)
        self.distance_km = distance_km

def weekly_report(workouts):
    total_cal = 0
    total_min = 0
    best = None
    for w in workouts:
        total_cal += w.calories
        total_min += w.minutes
        if best is None or w.calories > best.calories:
            best = w
    return {'total_calories': total_cal, 'total_minutes': total_min, 'best': best}
